"""Case18. Дано целое число в диапазоне 100–999. Вывести строку-описание данного числа, например: 256 — «двести пятьдесят шесть», 814 — «во- семьсот четырнадцать»."""
n=int(input()); h=["","сто","двести","триста","четыреста","пятьсот","шестьсот","семьсот","восемьсот","девятьсот"]; te=["десять","одиннадцать","двенадцать","тринадцать","четырнадцать","пятнадцать","шестнадцать","семнадцать","восемнадцать","девятнадцать"]; t=["","","двадцать","тридцать","сорок","пятьдесят","шестьдесят","семьдесят","восемьдесят","девяносто"]; o=["","один","два","три","четыре","пять","шесть","семь","восемь","девять"]; q=n%100; arr=[h[n//100]]; arr += [te[q-10]] if 10<=q<20 else ([t[q//10]] if q//10 else [])+([o[q%10]] if q%10 else []); print(" ".join(arr))
